const express = require("express");
const db = require("../db");

const router = express.Router();

// A retry with the same Idempotency-Key gets the original order back. A key
// reused with a different sku or quantity matches no row and gets a 422.
router.post("/", async (req, res) => {
  const key = req.get("Idempotency-Key") || null;
  if (key && key.length > 255) return res.status(400).end();
  const row = await db.write(
    `INSERT INTO orders (account_id, sku, quantity, idempotency_key) VALUES ($1, $2, $3, $4)
     ON CONFLICT (account_id, idempotency_key) DO UPDATE SET idempotency_key = EXCLUDED.idempotency_key
       WHERE orders.sku = EXCLUDED.sku AND orders.quantity = EXCLUDED.quantity
     RETURNING *`,
    [req.user.accountId, req.body.sku, req.body.quantity, key]
  );
  if (!row) return res.status(422).end();
  res.status(201).json(row);
});

router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row) return res.status(404).end();
  res.json(row);
});

module.exports = router;

