scoping.test.js.text:
// Run: node --test
// Stubs express and db so the update routes can be called directly.
const test = require("node:test");
const assert = require("node:assert");
const Module = require("module");

const handlers = {};
let lastWrite;
const route = (method) => (path, fn) => { handlers[`${method} ${path}`] = fn; };
const fakes = {
  express: { Router: () => ({ post: route("post"), patch: route("patch"), delete: route("delete") }) },
  // write() returns no row, as when the id belongs to another account or the
  // idempotency key was already used.
  "../db": {
    write: async (text, params) => { lastWrite = { text, params }; },
    query: async () => [{ id: 7 }],
  },
};
const load = Module._load;
Module._load = (request, ...rest) => fakes[request] || load(request, ...rest);
require("./routes/accounts");
require("./routes/orders");
Module._load = load;

for (const key of ["patch /:id", "delete /:id", "patch /:id/cancel"]) {
  test(`${key} is scoped to the session account`, async () => {
    const res = { statusCode: 200, status(c) { this.statusCode = c; return this; }, end() {}, json() {} };
    await handlers[key]({ params: { id: "2" }, body: {}, user: { accountId: 1 } }, res);
    const [, n] = lastWrite.text.match(/AND (?:id|account_id) = \$(\d+)/);
    assert.strictEqual(lastWrite.params[n - 1], 1);
    assert.strictEqual(res.statusCode, 404);
  });
}

test("post / with a used Idempotency-Key returns the existing order", async () => {
  let body;
  const res = { statusCode: 200, status(c) { this.statusCode = c; return this; }, json(b) { body = b; } };
  await handlers["post /"]({ get: () => "k1", body: {}, user: { accountId: 1 } }, res);
  assert.match(lastWrite.text, /ON CONFLICT \(account_id, idempotency_key\) DO NOTHING/);
  assert.deepStrictEqual(body, { id: 7 });
  assert.strictEqual(res.statusCode, 200);
});

