scoping.test.js.text:
// Run: node scoping.test.js — stubs express and db, no install needed.
const assert = require("node:assert");
const Module = require("node:module");

const db = { row: undefined, last: null, write: async (text, params) => { db.last = { text, params }; return db.row; } };
const load = Module._load;
Module._load = function (request, ...rest) {
  if (request === "../db") return db;
  if (request === "express") return { Router: () => {
    const r = {};
    for (const m of ["post", "patch", "delete"]) r[m] = (path, fn) => { r[`${m} ${path}`] = fn; };
    return r;
  } };
  return load.call(this, request, ...rest);
};

const accounts = require("./routes/accounts");
const orders = require("./routes/orders");
const user = { id: 1, accountId: 7 };

async function call(handler, id) {
  const res = { statusCode: 200, status(c) { res.statusCode = c; return res; }, end() {}, json(b) { res.body = b; } };
  await handler({ params: { id }, body: {}, user, get: () => "retry-1" }, res);
  return res;
}

(async () => {
  for (const handler of [accounts["patch /:id"], accounts["delete /:id"], orders["patch /:id/cancel"]]) {
    db.row = undefined; // another account's row: the scoped UPDATE matches nothing
    assert.strictEqual((await call(handler, "99")).statusCode, 404);
    assert.ok(db.last.params.includes(user.accountId), db.last.text);
    db.row = { id: 99 };
    assert.notStrictEqual((await call(handler, "99")).statusCode, 404);
  }

  // A retried POST /orders conflicts on its Idempotency-Key, so the INSERT
  // returns nothing and the route must return this account's existing order.
  db.row = undefined;
  db.query = async (text, params) => { db.last = { text, params }; return [{ id: 5 }]; };
  const res = await call(orders["post /"]);
  assert.deepStrictEqual([res.statusCode, res.body], [201, { id: 5 }]);
  assert.deepStrictEqual(db.last.params, [user.accountId, "retry-1"]);
  console.log("ok");
})();

