-- Nullable so clients that send no Idempotency-Key keep working: NULLs never
-- collide in a unique index. CONCURRENTLY avoids blocking order inserts while
-- the index builds, and cannot run inside a transaction block.
ALTER TABLE orders ADD COLUMN idempotency_key text;
CREATE UNIQUE INDEX CONCURRENTLY orders_account_id_idempotency_key
  ON orders (account_id, idempotency_key);

