const express = require("express");
const db = require("../db");

const router = express.Router();

router.patch("/:id", async (req, res) => {
  const row = await db.write(
    "UPDATE accounts SET display_name = $1, billing_email = $2 WHERE id = $3 AND id = $4 RETURNING *",
    [req.body.display_name, req.body.billing_email, req.params.id, req.user.accountId]
  );
  if (!row) return res.status(404).end();
  res.json(row);
});

router.delete("/:id", async (req, res) => {
  const row = await db.write("UPDATE accounts SET deleted_at = now() WHERE id = $1 AND id = $2 RETURNING id",
    [req.params.id, req.user.accountId]);
  if (!row) return res.status(404).end();
  res.status(204).end();
});

module.exports = router;

routes/orders.js.text:
const express = require("express");
const db = require("../db");

const router = express.Router();

// A retry with the same Idempotency-Key gets the original order back instead of
// creating a second one. Reusing a key for a different order is a 422.
router.post("/", async (req, res) => {
  const params = [req.user.accountId, req.body.sku, req.body.quantity, req.get("Idempotency-Key") || null];
  let row = await db.write(
    "INSERT INTO orders (account_id, sku, quantity, idempotency_key) VALUES ($1, $2, $3, $4) ON CONFLICT (account_id, idempotency_key) DO NOTHING RETURNING *",
    params
  );
  if (!row) {
    [row] = await db.query(
      "SELECT * FROM orders WHERE account_id = $1 AND sku = $2 AND quantity = $3 AND idempotency_key = $4",
      params
    );
    if (!row) return res.status(422).end();
  }
  res.status(201).json(row);
});

router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row) return res.status(404).end();
  res.json(row);
});

module.exports = router;

